solution:
public class DosSumMatriz {
    public static void main(String[] args) {
        int[][] matriz = {
            {1, 5, 3, 7},
            {9, 2, 8, 4},
            {6, 11, 23, 1}
        };
        int objetivo = 14;
        boolean encontrado = false;

        busqueda:
        for (int i = 0; i < matriz.length; i++) {
            for (int j = 0; j < matriz[i].length - 1; j++) {
                for (int k = j + 1; k < matriz[i].length; k++) {
                    if (matriz[i][j] + matriz[i][k] == objetivo) {
                        System.out.printf("Found: %d + %d = %d in row %d (positions %d and %d)%n",
                                matriz[i][j], matriz[i][k], objetivo, i, j, k);
                        encontrado = true;
                        break busqueda;  // exits all 3 loops
                    }
                }
            }
        }

        if (!encontrado) {
            System.out.println("Not found");
        }
    }
}
